SELECT DATE_TRUNC('YEAR', signup_date) AS year_start, CASE WHEN age >= 62 THEN 'PREMIUM' ELSE 'STANDARD' END AS age_tier, country, MAX(age) FILTER (WHERE segment = 'Corporate') AS corporate_max_age, COUNT_IF(segment = 'Corporate') AS corporate_events, SUM(age) FILTER (WHERE segment = 'Consumer') AS consumer_total_age, APPROX_PERCENTILE(age, 0.9) AS age_p90, PERCENT_RANK() OVER (PARTITION BY DATE_TRUNC('YEAR', signup_date) ORDER BY COUNT_IF(segment = 'Corporate') DESC) AS corporate_events_percent_rank FROM customers GROUP BY DATE_TRUNC('YEAR', signup_date), CASE WHEN age >= 62 THEN 'PREMIUM' ELSE 'STANDARD' END, country ORDER BY corporate_events;
